    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Um código pode ser roubado através da troca do SIM ou da portabilidade indevida do número, intercetado na rede telefónica ou introduzido numa página de início de sessão falsa e convincente. Ainda assim, é muito melhor do que usar apenas uma palavra-passe — ative esta opção para quem não pode usar uma aplicação de autenticação ou uma chave de acesso.',
