    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Uma flag de funcionalidade é um interruptor que as aplicações consultam para uma pessoa numa organização. Ative-a para utilizadores ou organizações específicos, ou para uma percentagem dos utilizadores. Todas as aplicações recebem a mesma resposta, na declaração `feature_flags` do token ou no endpoint de avaliação, sem nova implementação. Uma regra de utilizador prevalece sobre a da organização, que prevalece sobre a distribuição gradual, que prevalece sobre o valor predefinido.',
