    'it_is_called_again_at_the_hook_point_from_the_next_matc_a4d12b55' => 'Volta a ser chamado no ponto de execução do hook a partir da próxima operação correspondente.',
    'it_stops_being_able_to_act_as_you_immediately_and_has_t_5c3d584b' => 'Deixa imediatamente de poder agir em seu nome e terá de pedir novamente a sua aprovação.',
    'it_stops_being_called_at_the_hook_point_the_operation_i_72937229' => 'Deixa de ser chamado no ponto de execução do hook. A operação a que respondia prossegue sem ele.',
    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Deixa de funcionar imediatamente. Tudo o que ainda o utilize deixa de conseguir iniciar sessão.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Usa PKCE e não recebe nenhum segredo — não há nada que possa vazar do navegador ou do telemóvel.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'A partir de agora, os seus eventos são aceites sem verificação — ou recusados, se o modo estrito estiver ativado.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Os seus membros podem voltar a iniciar sessão e os seus ambientes retomam a autenticação.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'As suas próprias credenciais, em vez das credenciais do ambiente para este fornecedor.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Chave criada. Cole-a no frontend — destina-se a ser pública.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Chave substituída — copie agora a nova. A chave antiga continua a funcionar durante 24 horas.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Apresenta botões do Google, GitHub, Apple e outros na página de início de sessão, para quem prefere usar uma conta existente a criar outra palavra-passe. Configure cada fornecedor uma vez para o ambiente e todas as organizações poderão usá-lo. Cada organização pode usar as suas próprias credenciais ou desativar um fornecedor. Basta fornecer as credenciais; os restantes campos são preenchidos automaticamente. Um endereço enviado pelo fornecedor nunca é suficiente, por si só, para aceder a uma conta existente aqui.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'As chaves que o seu código apresenta ao Cbox ID, com um separador por tipo. Uma chave secreta, ou chave de gestão, permite ao backend gerir organizações, membros, convites, funções e aplicações de um ambiente. Uma chave de organização chama a API da organização com uma função predefinida. Uma chave publicável é usada numa aplicação de navegador e funciona apenas nas origens autorizadas. As chaves secretas e de organização são mostradas uma única vez: copie-as ao criá-las e revogue-as imediatamente se forem expostas.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Regista aplicações que aceitam este ambiente como fornecedor de identidade SAML, permitindo aos utilizadores iniciar sessão com as contas que já têm aqui. Associe cada aplicação à organização a que pertence para limitar o acesso aos seus membros. Sem organização associada, a aplicação fica disponível para todos os utilizadores do ambiente. Esta é a direção de saída. Para permitir a entrada com contas empresariais de outros sistemas, use SSO empresarial em Autenticação.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Escolha o framework com que trabalha. Será criada uma aplicação com um redirecionamento para o servidor de desenvolvimento local, o bloco de configuração do ambiente para copiar e o código de início de sessão. A página aguarda até alguém iniciar sessão de facto. Abaixo surgem os passos para preparar o produto: identidade visual, organizações, início de sessão único, um agente, um colega e produção. Cada passo é assinalado com base nos dados do ambiente, nunca manualmente.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'O Radar avalia cada início de sessão e registo: tentativas com credenciais roubadas, velocidade típica de bots, deslocações impossíveis, novos dispositivos, redes de anonimização e endereços descartáveis, além das suas regras e listas de permissões e bloqueios. Regista cada decisão e, quando ativa a aplicação das regras, bloqueia o acesso ou exige um segundo fator. Consulte as decisões aqui antes de ativar a aplicação das regras e sempre que alguém não conseguir iniciar sessão.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Controlos de funcionalidades que as aplicações consultam para uma pessoa numa organização. Ative uma funcionalidade para utilizadores específicos, organizações específicas ou uma percentagem de todos. Todas as aplicações leem a mesma resposta, no token ou através da API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Software que atua neste ambiente com uma chave de gestão: Claude Code, Cursor, um bot interno ou o seu próprio backend. Cada um dispõe apenas dos âmbitos de acesso que lhe atribuiu e aguarda a sua aprovação quando assim o definiu.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'O recetor mantém o mesmo segredo. Um segredo hexadecimal de 64 caracteres passa a ser whsec_ seguido da codificação base64 dessa cadeia hexadecimal — "whsec_" + base64(secret). Um segredo que já começa por whsec_ é usado tal como está.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizações, utilizadores e sessões ativas de todos os ambientes desta instalação, bem como as organizações com mais membros. Esta vista apenas consulta dados e nunca altera o ambiente selecionado na consola.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Todas as pessoas que podem iniciar sessão nesta organização e os convites enviados que ainda não foram aceites. Convide pessoas por e-mail; cada uma configura o seu próprio acesso, pelo que nunca tem de gerir a palavra-passe de outra pessoa.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Permita que as pessoas iniciem sessão com uma conta que já têm. Configure um fornecedor uma vez para o ambiente e ficará disponível em todas as organizações. Uma organização pode usar as suas próprias credenciais ou desativar um fornecedor.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'O Radar avalia cada início de sessão e registo: tentativas com credenciais roubadas, rapidez típica de bots, deslocações impossíveis, novos dispositivos, redes que ocultam a identidade, endereços descartáveis e as suas próprias regras e listas. Regista também o motivo da decisão.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Este utilizador deixa de poder iniciar sessão em qualquer aplicação deste ambiente. As sessões existentes deixam de funcionar no pedido seguinte. Os seus registos são mantidos e pode reativá-lo a qualquer momento.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'A avaliação segue esta ordem: lista de bloqueio, lista de permissões, regras personalizadas de cima para baixo (decide a primeira correspondência) e regras integradas (decide a mais restritiva das que se aplicam). Se nada corresponder, o acesso é permitido.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'A maioria das integrações deve usar webhooks: são executados depois do evento e não podem bloquear a operação. Use um hook apenas quando o seu sistema tiver de intervir durante um início de sessão ou a emissão de um token.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'As chaves que criar aparecem aqui, com a data da última utilização de cada uma.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Deixe em branco para não bloquear — nesta instalação, o bloqueio está desativado por predefinição.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Permita que as pessoas iniciem sessão com a conta da empresa que já têm, em vez de uma palavra-passe separada aqui.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Fluxo de registos guardado. A entrega será tentada novamente na próxima execução.',
