    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Quando alguém termina sessão, ou um administrador termina as sessões, remove ou desativa a pessoa, o Cbox ID envia um token de fim de sessão assinado para este endereço, de servidor para servidor, para a aplicação também terminar a sua sessão.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'O destino para onde o Cbox ID encaminha as pessoas depois de terminarem sessão nesta aplicação. O URI pedido pela aplicação tem de corresponder exatamente a um URI desta lista, incluindo a barra final. Caso contrário, o Cbox ID mantém a pessoa na sua própria página de sessão terminada. Deixe vazio se a aplicação nunca redirecionar as pessoas após terminarem sessão.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Onde esta aplicação publica as funções que reconhece, para que possam ser atribuídas aqui.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'As formas de início de sessão que :part1 oferece além da palavra-passe e a duração de uma sessão. São iguais para todas as organizações do ambiente.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Quem pertence a esta organização e o que pode fazer. Quem ainda não tem conta aqui recebe um convite por e-mail.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Para quem o sinalizador de funcionalidade está ativo quando nenhuma regra se aplica. Deixe desativado para disponibilizar primeiro a funcionalidade a organizações específicas ou a uma percentagem de utilizadores.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'A quem pertence a função, ou selecione a opção acima para a definir para todas as organizações.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'De quem são as funções e adesões registadas pela revisão.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'A quem pertence a regra, ou selecione a opção acima para a aplicar a todas as organizações.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Sem funções, qualquer pessoa que consiga iniciar sessão recebe o acesso que a aplicação dá a um utilizador comum. Uma função permite definir uma vez quem são os editores e quem é a equipa de apoio, para que todas as aplicações ligadas respeitem essa atribuição.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Percorra a lista: confirme o que ainda é necessário e revogue o que já não é.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Adicione um registo acima ou envie registos a partir do servidor da aplicação em lotes de até 100.',
    'writes_531995e8' => 'escrita',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'É o único proprietário. Transfira primeiro a propriedade para outra pessoa ou elimine a organização.',
    'you_can_also_part1_part2_part3_53f32513' => 'Outra opção: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'Pode voltar a definir «Preferir SSO» ou «Ambos disponíveis» a qualquer momento. As sessões terminadas não são reabertas.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Pode voltar a definir «Preferir SSO» ou «Ambos disponíveis» a qualquer momento. As sessões terminadas não são reabertas.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Perde o acesso imediatamente. Como proprietário, só pode sair depois de outra pessoa assumir a propriedade. Transfira-a primeiro ou elimine a organização nas Definições.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Perde imediatamente o acesso a esta organização e às suas aplicações. Um administrador pode voltar a convidá-lo.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'O modelo de acesso da sua aplicação: tipos de recursos, relações de cada tipo e a forma como herdam acesso. A aplicação escreve tuplos, indicando quem se relaciona com o quê, e consulta as permissões em cada pedido.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'A política de autenticação continua a aplicar-se: segurança da palavra-passe, verificação de fugas de dados, confirmação de e-mail, limites de pedidos e verificações de bots.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'A sua própria API. Escolhe, âmbito a âmbito, quais podem ser pedidos por aplicações registadas pelas organizações.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'A página de início de sessão passa a ter uma ligação «Criar conta», e as aplicações podem encaminhar as pessoas diretamente para o registo com :part1.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "ID da pessoa",
  "org": "a organização em nome da qual atua",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'api_read_reports_export_db00448d' => 'api.read, reports.export',
    'billing_read_reports_write_36538bcc' => 'billing:read, reports:write',
    'document_readme_29e90756' => 'document:readme',
    'document_readme_viewer_user_alice_f9405db5' => 'document:readme#viewer@user:alice',
    'https_app_example_com_https_staging_example__ad77bfc7' => 'https://app.example.com
https://staging.example.com',
    'invoices_create_be35ad14' => 'invoices:create',
    'invoices_read_459482fd' => 'invoices:read',
    'user_alice_dabd1db8' => 'user:alice',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'As funções e permissões num token são um retrato de um momento. Antes de cada ação protegida, obtenha uma decisão de acesso atual do Cbox ID e verifique na aplicação o acesso ao recurso concreto. O conteúdo do token, por si só, não reflete revogações posteriores:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Os seus métodos de início de sessão e sessões ativas. Uma chave de acesso é a opção mais segura e rápida: o dispositivo desbloqueia-a com a impressão digital ou o rosto, sem uma palavra-passe que possa ser roubada por phishing.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Cada ação é aceite tal como a aplicação a envia. Adicione um esquema a uma ação para validar os respetivos eventos à chegada. A consistência do registo garante-se quando o evento é escrito, não quando alguém o consulta.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Cada chave de API guardada na configuração ou no ficheiro de ambiente de uma aplicação é uma chave que não pode substituir centralmente nem revogar rapidamente. Guardada aqui, fica encriptada, é autorizada por aplicação e pode ser revogada com um clique.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'O botão deixa de aparecer e as credenciais são eliminadas. Quem iniciou sessão com este fornecedor mantém a conta e pode continuar a usar a palavra-passe. Para manter as credenciais, desative o fornecedor em vez de o eliminar.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'O sentido inverso: o Cbox ID envia as pessoas da sua organização para os outros produtos SaaS usados pela empresa, através dos endpoints SCIM desses produtos. Um único local para conceder e retirar acesso, em vez de um painel de administração por fornecedor.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Cria a organização, o proprietário, o primeiro produto e o ambiente de produção desse produto. O proprietário recebe por e-mail uma ligação para definir a sua própria palavra-passe; não a escolhe por ele.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Atualmente, as pessoas são adicionadas e removidas aqui manualmente. Ligue o diretório que a empresa já mantém e ambos os processos passam a ser automáticos, incluindo as remoções, que são as mais fáceis de esquecer.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Todos os tokens que emitiu são revogados agora e nenhum novo início de sessão o pode usar. Uma aplicação que valida os tokens por si própria deixa de os aceitar quando expiram, sempre até ao fim da própria sessão.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Durante a migração de outro sistema, a aplicação pode indicar onde está o início de sessão antigo no seu manifesto, junto das funções. Essa indicação aparece aqui para aprovação antes de produzir qualquer efeito.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Crie uma regra para permitir, exigir verificação adicional ou bloquear com base no que sabe sobre os utilizadores: peça verificação adicional em inícios de sessão de países onde não opera ou isente a rede do escritório das regras de frequência.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Verificar um domínio que lhe pertence, como acme.com, permite ao Cbox ID reconhecer as suas pessoas pelo endereço de e-mail e encaminhá-las diretamente para o seu fornecedor, sem terem de escolher o botão de início de sessão correto.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Um fornecedor de identidade que importa metadados do fornecedor de serviço usa este URL em vez de receber separadamente o ID da entidade e o URL ACS. Funciona mesmo antes de preencher a configuração do fornecedor de identidade.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Esta ação não pode ser anulada. As credenciais, as associações a organizações e os dados pessoais são eliminados, e a conta é pseudonimizada. Se esta pessoa for a única proprietária de uma organização, transfira primeiro a propriedade.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Age como esta pessoa, na sessão dela e com o acesso dela. A sessão está limitada a 30 minutos e a leitura onde a consola o consegue impor. Cada pedido fica registado em seu nome.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'A suspensão é a única alteração feita nesta página e é reversível. Selecionar e abrir um ambiente apenas muda a vista da consola; não altera nada em nenhum dos ambientes.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Atualmente, as pessoas iniciam sessão com credenciais guardadas aqui. Ligue o seu fornecedor para usarem a conta da empresa que já têm e perderem o acesso aqui assim que a desativar no fornecedor.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Não é emitido um novo segredo. A partir da tentativa seguinte, incluindo repetições, as entregas passam a usar os cabeçalhos do outro esquema. Um recetor que não tenha sido atualizado rejeitará todas essas entregas.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Envie esta ligação de utilização única a quem gere o fornecedor de identidade, caso não a tenha recebido por e-mail. Funciona sem conta até expirar. Copie-a agora: só é apresentada uma vez.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'O software deste ambiente que aguarda autorização de uma pessoa. Um agente cuja chave exige aprovação para e pede autorização à pessoa que criou a chave. Responda aqui ou no telemóvel.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Uma organização reúne utilizadores, métodos de início de sessão e funções. Crie uma acima ou inicialize o ambiente com a primeira organização e o primeiro administrador no ecrã Ambientes.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Adicione esta pessoa a uma das organizações abaixo para lhe dar acesso dentro dela. Se as suas aplicações não tiverem separação própria por organização, atribua-lhe uma função de administração e apoio, válida em todo o ambiente.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Uma função de administração e apoio é atribuída à sua própria equipa em todo o ambiente: aplica-se a todas as organizações e nenhum administrador de uma organização a pode ver ou alterar.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Os pedidos aparecem aqui automaticamente quando uma aplicação ou agente precisa da sua aprovação para agir em seu nome. Não tem de fazer nada enquanto não houver pedidos. Se aparecer um pedido que não iniciou, recuse-o.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'As mensagens SMS são o segundo fator menos seguro: quem assumir o controlo do seu número de telefone recebe os seus códigos. Prefira uma aplicação de autenticação ou uma chave de acesso; use SMS apenas se não puder usar essas opções.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'A identidade visual predefinida do ambiente: o aspeto, logótipo e favicon da página de início de sessão alojada, bem como o nome e o remetente apresentados às pessoas. Todas as organizações a herdam, salvo se definirem a sua própria.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Detalhes da organização no ambiente de destino: membros, SSO, domínios, direitos de acesso e atividade recente. Esta página só permite alterar o estado da organização.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Todas as organizações desta instalação. Abra um para consultar os seus produtos e ambientes. Suspendê-lo termina as sessões dos membros e impede todos os seus ambientes de processar autenticação.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'A aplicação envia estes eventos, numa chamada por lote, e cada evento identifica a organização onde ocorreu. Aparecem aqui e para os administradores da respetiva organização à medida que chegam.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Está disponível em todas as páginas de início de sessão do ambiente. Selecione uma organização para configurar uma opção própria, que substitui a do ambiente na página dessa organização.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'O Claude Code abre o navegador para iniciar sessão aqui e pergunta o que pretende autorizar. Não precisa de guardar uma chave. Qualquer cliente MCP que use OAuth para iniciar sessão funciona da mesma forma com este URL.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Uma organização desta instalação: a equipa, os projetos e todos os ambientes desses projetos. Suspendê-lo termina as sessões dos membros e impede todos esses ambientes de processar autenticação.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Em todo o ambiente: qualquer pessoa com conta neste ambiente, em qualquer organização, pode iniciar sessão nesta aplicação. Indique uma organização, a menos que pretenda esse acesso abrangente.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'O início de sessão com Entra ID, Okta ou Google Workspace está disponível no plano Enterprise. Contacte a equipa responsável pela sua conta para o ativar nesta organização.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Onde tem sessão iniciada, o que pode agir em seu nome e o que aconteceu à sua conta. Se vir algo que não reconhece, termine essa sessão e altere a palavra-passe.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Quantas pessoas iniciaram sessão e quantas vezes as aplicações chamaram a API nos últimos 30 dias. Estes dados ajudam a acompanhar a carga e detetar anomalias; não são uma fatura.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Este utilizador é proprietário ou administrador de uma organização e não é permitido assumir a sua identidade. Fazê-lo daria a quem entrasse na conta controlo duradouro sobre a organização.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Chaves de API que as aplicações e os agentes apresentam a outros serviços. Cada valor é encriptado em repouso, entregue apenas às aplicações autorizadas e nunca volta a ser mostrado depois de o guardar.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplicações que pedem para agir em nome de um dos seus utilizadores. Cada utilizador aprova os seus próprios pedidos. Recuse um aqui apenas se parecer abusivo; a recusa fica registada no registo de auditoria.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'A frequência de importação e os campos do sistema de RH a copiar para cada pessoa, como centro de custos ou localização. Alterar os campos faz com que a execução seguinte seja completa.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Ligações entregues ao administrador de TI desta organização que ainda dão acesso. Revogar uma ligação invalida-a imediatamente; o que já foi configurado através dela mantém-se.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Os pedidos de agentes para agir em nome de um utilizador aparecem aqui à medida que chegam. Cada utilizador aprova os seus próprios pedidos. Esta página serve para recusar pedidos que pareçam abusivos.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Quando TODAS as condições se verificam, o Radar executa a ação desta regra e não avalia as seguintes. As regras são avaliadas depois das listas de permissões e bloqueio e antes das regras integradas.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Os eventos de auditoria que a aplicação envia sobre todas as organizações que serve, do mais recente para o mais antigo. Os eventos de cada organização formam a sua própria cadeia de hashes.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Tudo o que a organização já configurou e o que falta fazer. A lista de configuração acompanha o estado real: cada etapa é marcada automaticamente quando está efetivamente concluída.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Como administrador, adicione também uma aplicação de autenticação ou uma chave de acesso. Quem assumir o controlo do seu número pode receber os SMS, por isso estes não podem ser o seu único segundo fator.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Eliminar esta organização elimina todos os projetos e ambientes que lhe pertencem. Para proteger os fornecedores de identidade em funcionamento, esta ação não está disponível em autosserviço. Contacte o apoio para prosseguir.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Esta pessoa perde imediatamente acesso a todas as páginas da plataforma nesta instalação e as sessões existentes deixam de funcionar no pedido seguinte. Pode reativá-la aqui.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Os domínios verificados encaminham as pessoas para o seu fornecedor de identidade, uma funcionalidade do plano Enterprise. Contacte a equipa responsável pela sua conta para a ativar nesta organização.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Uma permissão é algo que uma função pode fazer, como criar faturas ou ler relatórios. Pode criar permissões aqui, sem código, e depois agrupá-las em funções. As aplicações também podem registar as suas automaticamente, mantendo a lista alinhada com o que realmente verificam. As permissões que cria pertencem-lhe. Pode usar as partilhadas pelo ambiente, mas não alterá-las.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'As regras de palavras-passe, bloqueio, exigência de dois fatores e de início de sessão único aplicadas em cada início de sessão. Para todo o ambiente, também definem se são disponibilizadas chaves de acesso e ligações de acesso e quanto tempo dura uma sessão. O ambiente estabelece uma base herdada por todas as organizações. Cada organização pode tornar as regras de palavras-passe e de dois fatores mais rigorosas, mas nunca menos.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'As ações que os agentes deste ambiente aguardam que uma pessoa autorize. Se a chave de um agente exigir aprovação para uma ação, o agente para e pede autorização à pessoa que criou a chave, que pode responder no telemóvel ou aqui. Quem administra este ambiente pode recusar pedidos suspeitos. Abaixo surgem pedidos de aplicações para agir em nome dos utilizadores, que cada utilizador aprova por si.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'As sessões e os tokens da pessoa são revogados. As chaves de acesso, segundos fatores, participações, atribuições de funções, tokens de API, segredos do cofre, dispositivos e todas as cópias guardadas dos seus dados são eliminados. Da conta fica apenas um registo pseudonimizado e desativado. As aplicações que sincronizam pessoas a partir daqui são notificadas para a eliminar. O registo de auditoria conserva o identificador opaco, sem o nome nem o endereço.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Tudo o que autorizou, incluindo dispositivos ou ferramentas de linha de comandos em que iniciou sessão.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Dados que os seus sistemas precisam de guardar sobre esta organização. As linhas sem chave são descartadas.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Avaliadas depois das suas regras. Todas as regras acionadas são registadas; prevalece a mais restritiva.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'A entrega é retomada. Os registos criados enquanto estava desativada continuam pendentes e serão enviados no próximo lote.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'A entrega para imediatamente e a credencial guardada é destruída. O registo de auditoria mantém-se intacto.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Todas as ligações entre o Cbox ID e outros sistemas, num só lugar: início de sessão único, início de sessão social, sincronização de diretórios e sistemas de RH, aprovisionamento de saída, aplicações SAML, webhooks, hooks, fluxos de registos e pipes. O catálogo permite começar qualquer uma delas: cada cartão abre a página de configuração desse tipo. A lista de ligações mostra todas as ligações existentes e o seu estado, com as que falham em primeiro lugar.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Todas as formas de iniciar sessão aqui — palavra-passe, chaves de acesso, ligação de acesso, conta social, SSO empresarial e segundo fator — com indicação de estarem ativas e de onde se alteram. A maioria é definida pelo ambiente; as ligações SSO pertencem a cada organização. Quando a instalação desativa ou limita um método, a página indica-o e identifica a definição responsável.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Um agente é qualquer software que atua neste ambiente com uma chave de gestão: um assistente de IA como Claude Code ou Cursor, um bot interno ou o seu próprio backend. Dê a cada um uma chave própria, apenas com os âmbitos necessários, escolha as ações que aguardam aprovação e revogue a chave assim que o agente terminar ou algo parecer errado.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Uma API é um serviço seu que recebe tokens de acesso, como https://api.example.com. Registe-a com os âmbitos que reconhece para poder atribuí-los. Decide quais desses âmbitos podem ser pedidos pelas aplicações registadas pelas organizações deste ambiente. O token destinado à API inclui o endereço dela como audiência, que o seu serviço deve verificar.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Como o registo de auditoria sai do Cbox ID: uma exportação agendada envia novas entradas para o SIEM ou arquivo a cada cinco minutos. Uma tarefa diária de retenção cria um ponto de controlo do registo sem eliminar dados. Use esta página para obter o histórico de auditoria de uma pessoa em resposta a um pedido de acesso ao abrigo do RGPD ou, na consola de ambiente, para verificar se as exportações estão a funcionar.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Crie um em Plataforma › Ambientes e as respetivas contagens aparecerão aqui.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Todos os ambientes desta instalação e a dimensão de cada um',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Todas as filas de tarefas em segundo plano desta instalação e o tempo de espera da tarefa mais antiga de cada uma',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Todos os contadores de utilização deste período e a chave original da métrica correspondente',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Encontre uma organização ou um utilizador em todos os ambientes, não apenas no ambiente atual da consola.',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Um único processo de execução contínua, php artisan queue:autoscale, inicia e para os processos de trabalho que executam as tarefas em fila.',
    'account_menu_value0_6ab6a9a2' => 'Menu da conta — :value0',
    'acme_inc_ee60673d' => 'Acme Inc.',
    'disconnect_value0_1d09db11' => 'Desligar :value0?',
    'remove_value0_b597e5fb' => 'Remover :value0',
    'remove_value0_b8b38a7a' => 'Remover :value0?',
    'rename_value0_b709cc6f' => 'Mudar o nome de :value0',
    'trial_98a66e97' => 'Avaliação',
    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Não incluído no plano desta organização.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Nenhum domínio reivindicado corresponde à pesquisa. Experimente parte do domínio, sem @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Nenhuma ligação corresponde a esse nome. Experimente outro termo de pesquisa.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Nenhum diretório corresponde a esse nome. Experimente outro termo de pesquisa.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Nenhum URL de endpoint corresponde à pesquisa. Experimente outra pesquisa.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Nenhum registo corresponde a estes filtros. Experimente um termo mais abrangente ou remova um filtro.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Nenhum fluxo de registos corresponde a esse nome. Experimente outra pesquisa.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Nenhuma ligação de saída corresponde a esse nome. Experimente outra pesquisa.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Tudo o que os utilizadores veem da sua marca numa só página: logótipo, favicon, cores, tipo de letra e cantos do início de sessão alojado, com pré-visualização imediata, além do nome do produto, remetente de email e mensagem de boas-vindas. Configure uma vez para todo o ambiente e todas as organizações herdam as definições, ou personalize uma organização no separador Identidade visual.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Cada projeto da organização tem o seu próprio plano e limite de ambientes, apresentados aqui junto à utilização deste mês: organizações, ligações de início de sessão único faturadas e inícios de sessão. O preço considera os utilizadores ativos mensais e as ligações empresariais, como início de sessão único e SCIM. Os ambientes de testes não têm custos de ligação.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Todas as chaves de API criadas pelos membros desta organização para as suas aplicações: titular, aplicação, permissões e última utilização. Uma chave só pode fazer o que o titular pode e deixa de funcionar quando este sai da organização. Revogue as chaves expostas ou sem utilização. Cada pessoa cria as suas próprias chaves em A minha conta.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Durante a migração de outro sistema, uma aplicação pode pedir a validação do email e da palavra-passe de quem ainda não existe no Cbox ID no antigo endpoint de início de sessão. Teste o endpoint antes de o aprovar: uma pessoa aceite é criada aqui e nunca mais é enviada ao sistema antigo. Porém, enquanto esse endpoint estiver indisponível, quem ainda não migrou não poderá iniciar sessão.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Os eventos de auditoria que a sua aplicação envia sobre cada organização que utiliza o produto: quem fez o quê e quando. São guardados por organização numa cadeia de hashes e apresentados aos administradores dessa organização. Use esta função quando uma organização pedir um registo de auditoria da sua conta. Defina esquemas para manter a consistência dos eventos.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Nenhuma concessão de acesso futura poderá abrir este segredo. A revogação é imediata e permanente.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Não há agentes ativos. As chaves revogadas e expiradas mantêm-se na lista para consulta.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Sem permissões: apenas identifica o titular',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Nada muda para ninguém enquanto esta opção não estiver ativada. Teste primeiro um início de sessão.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Só é guardado um hash. Se perder a chave, revogue-a e crie outra.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Só as aplicações aqui indicadas podem obter acesso temporário a este segredo. Todos os outros pedidos são recusados.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'As sessões em todos os outros dispositivos deixam de funcionar no próximo pedido. Este dispositivo mantém a sessão iniciada.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Esta organização ainda não tem membros. Ninguém pode iniciar sessão nela até que seja convidado ou adicionado por provisionamento.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Não é definida nenhuma palavra-passe aqui. A pessoa recebe uma ligação de início de sessão por email e escolhe como iniciar sessão.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Cada passo é avaliado com base no estado atual, pelo que o guia mostra sempre a situação real desta organização.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Copie a chave agora e entregue-a ao agente. Só é guardado um hash, pelo que esta é a única vez que a chave é apresentada.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Os domínios de email desta organização, cada um comprovado por um registo DNS TXT. Depois de verificar um domínio, pode ativar o encaminhamento obrigatório para SSO: todos os utilizadores com um endereço nesse domínio passam a usar a ligação SSO empresarial em vez de uma palavra-passe. Verifique todos os domínios usados pelas pessoas antes de depender do início de sessão único.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'O modelo de acesso da sua aplicação: tipos de recursos, como documentos e pastas, relações, como proprietário, editor e leitor, e a sua herança. Por exemplo, quem pode ver uma pasta pode ler todos os documentos nela. A aplicação regista quem se relaciona com cada recurso e pergunta em cada pedido se o utilizador pode editar aquele documento. O esquema determina a resposta.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Este ambiente disponibiliza um servidor MCP, o padrão usado por assistentes de IA para chamar ferramentas, juntamente com a API REST. Cole o endereço e uma chave de gestão no Claude Code, Cursor ou outro cliente MCP. O agente poderá fazer exatamente o que os âmbitos da chave permitem, com as mesmas verificações e o mesmo registo de auditoria da consola.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Uma chave permite aos seus scripts e integrações chamar a API de uma aplicação em seu nome, sem iniciar sessão. Só pode fazer o que lhe é permitido nessa aplicação: se perder algum acesso, a chave também o perde. A chave é mostrada uma única vez. Copie-a ao criá-la e revogue-a imediatamente se for exposta ou deixar de ser usada.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'O provisionamento para e os mapeamentos de grupos são removidos. As pessoas criadas mantêm-se.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'O provisionamento para imediatamente e todos os mapeamentos de grupos são removidos. Esta ação é irreversível.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'O provisionamento para a aplicação de destino para imediatamente. Esta ação é irreversível.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'O provisionamento para a aplicação de destino para imediatamente. As pessoas já criadas nessa aplicação mantêm-se.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Número de telefone removido. Os outros fatores e códigos de recuperação da pessoa mantêm-se inalterados.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'As pessoas já ligadas mantêm os âmbitos que autorizaram até voltarem a ligar-se.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Origens atualizadas. A alteração entra em vigor no próximo pedido.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Outros sistemas podem estar a utilizá-lo. Alterá-lo muda os URL que esses sistemas guardaram.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'As pessoas que dependem deste fornecedor perdem esta forma de iniciar sessão. Esta ação é irreversível.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Projeto suspenso. Os seus ambientes continuam ativos, mas não é possível adicionar novos até que o projeto seja reativado.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Definição da função ativada. Os atuais titulares passam a utilizar estas permissões.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Regra ativada. A partir de agora, são bloqueadas as atribuições que a violem.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Esquema guardado. A partir de agora, os eventos desta ação são validados de acordo com ele.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Esquema guardado. A partir de agora, todas as verificações são decididas de acordo com ele.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Recuse eventos cuja ação não tenha esquema. Ative esta opção quando todas as ações enviadas pela aplicação tiverem um.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Os objetos são gravados em prefix/yyyy/mm/dd/hh/batch.ndjson.gz, com um evento por linha.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Apenas para armazenamento compatível com S3, como MinIO ou Cloudflare R2. Se ficar vazio, é utilizado o endpoint AWS da região.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Registe este URI de redirecionamento permitido no fornecedor, exatamente como apresentado.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Os webhooks, avisos de fim de sessão para aplicações ligadas, atualizações de funções obtidas dessas aplicações e emails em fila são processados em segundo plano por processos de fila, sem fazer a pessoa esperar. Se nenhum processo estiver a funcionar, nada será enviado, embora o resto da consola pareça normal. É nesta página que deteta o problema.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Uma revisão em que verifica quem tem cada função e confirma se ainda precisa dela. O acesso acumula-se sem se notar: as pessoas mudam de equipa e mantêm permissões antigas. A revisão permite remover esse acesso. As revogações são aplicadas ao encerrar a revisão, e todo o processo fica registado para auditoria.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Se a aplicação declarar outro URL mais tarde, esta aprovação é anulada e será pedida novamente. Uma mudança no destino das palavras-passe exige nova aprovação. O início de sessão delegado serve de transição: quando restarem poucas pessoas no sistema antigo, desative-o e envie-lhes uma reposição de palavra-passe.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Permite às pessoas iniciar sessão com a conta empresarial que já têm, como Microsoft Entra ID, Okta ou Google Workspace, em vez de uma palavra-passe separada aqui. Ligue o fornecedor de identidade uma vez e confirme os seus domínios de email. Todos os utilizadores desses domínios serão encaminhados para o fornecedor para iniciar sessão.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Todas as pessoas com uma identidade neste ambiente, independentemente das organizações a que pertencem. Abra uma pessoa para repor a palavra-passe ou o segundo fator, terminar as sessões, desativar a conta, alterar as organizações e funções atribuídas ou eliminar os dados definitivamente em resposta a um pedido de apagamento.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Cole o XML de metadados do fornecedor ou o URL dos metadados e os campos abaixo serão preenchidos automaticamente.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Cole este valor no seu fornecedor de identidade, juntamente com o token bearer do diretório que vai ligar.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Configure o seu cliente OIDC com estes endereços. A descoberta disponibiliza automaticamente todos os endpoints.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Registe uma aplicação que utilize este ambiente como fornecedor de identidade SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Registe uma para permitir que uma aplicação autentique os utilizadores com as contas que já têm neste ambiente.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Só as aplicações aqui indicadas recebem um token. Todos os outros pedidos são recusados.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Não há direitos de utilização definidos para esta organização. São utilizados os valores predefinidos da instalação.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Organizações do ambiente selecionado, apresentadas na árvore de gestão.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Pertence a este ambiente, e não a uma organização',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Os operadores da plataforma administram ambientes em toda a instalação.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Utilização de toda a plataforma em todos os ambientes, não apenas no ambiente atual da consola.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'A forma como os proprietários e operadores das organizações iniciam sessão no Cbox ID é definida na consola do ambiente da plataforma.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Estes pontos de extensão são executados durante uma operação, não depois, e a sua resposta altera o resultado: o seu endpoint pode acrescentar informação a um token ou recusar um início de sessão. Intervêm diretamente no processamento da operação: se o endpoint estiver lento ou falhar, a pessoa que tenta iniciar sessão será afetada.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'O seu fornecedor de identidade cria, atualiza e desativa pessoas aqui automaticamente através da norma SCIM. A entrada ou saída de alguém no sistema de recursos humanos chega às aplicações em segundos, sem pedidos de suporte nem contas esquecidas — algo especialmente importante quando alguém sai.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'O número de organizações, utilizadores, ligações de início de sessão único, aplicações e sincronizações de utilizadores deste ambiente, com ligação para a respetiva página. Os atalhos abaixo iniciam as criações mais frequentes: uma organização, um utilizador, uma ligação de início de sessão único ou uma aplicação.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Uma função representa uma responsabilidade que as suas aplicações reconhecem, como «Editor» ou «Agente de suporte». Aqui decide quem tem cada função; cada aplicação decide o que as suas funções permitem fazer. As funções acompanham a pessoa em todas as aplicações ligadas, para conceder e revogar acesso num só local.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Envia uma cópia de cada entrada do registo de auditoria para as ferramentas da equipa de segurança, como um SIEM, assim que é escrita. Configure um destino para começar as investigações nas ferramentas já usadas pela equipa, sem pedir uma exportação. A entrega é feita pelo menos uma vez, pelo que podem ocorrer duplicados.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Uma organização aparece aqui assim que alguém se regista. Também pode usar Nova organização acima para criar um.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Adicione o domínio dos endereços de email das pessoas desta organização, publique o registo TXT e verifique o domínio.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Comprove que é proprietário de um domínio de email para encaminhar automaticamente a sua equipa para o SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Comprove que a organização é proprietária de um domínio e encaminhe todas as pessoas desse domínio para o início de sessão da organização.',
    'sandbox_environments_send_no_email_copy_the_setup_link_e5709a6a' => 'Os ambientes de teste não enviam emails. Copie a ligação de configuração abaixo e partilhe-a diretamente.',
    'it_replaces_the_sealed_value_on_rotate_and_is_never_sho_cec701f1' => 'Na rotação, substitui o valor cifrado e nunca volta a ser apresentado. Guarde uma cópia se precisar.',
    'replace_the_sealed_value_with_a_new_credential_the_stor_17b46d38' => 'Substitua o valor cifrado por uma nova credencial. O valor guardado nunca é apresentado.',
    'sealed_the_moment_you_save_it_and_never_shown_again_kee_db995569' => 'É cifrado assim que o guarda e nunca volta a ser apresentado. Guarde uma cópia se precisar.',
    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'É guardado cifrado e nunca volta a ser apresentado. Deixe em branco para manter o atual.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Segredo substituído. O anterior deixou de funcionar. Copie o novo agora: não voltará a ser apresentado.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'A revogação é imediata e permanente. Nenhuma concessão de acesso futura poderá abrir este segredo.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Os esquemas de metadados são um subconjunto de JSON Schema: um objeto cujas propriedades podem ser cadeias de caracteres, números, inteiros, booleanos ou null, com enumerações e restrições de comprimento, intervalo, padrão e formato. Guardar uma alteração cria uma nova versão; os eventos já registados mantêm a versão usada na sua validação.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Cada ligação permite às pessoas ligar a sua própria conta num serviço como GitHub, Google ou Slack. Os tokens são guardados encriptados e mantidos atualizados aqui. As aplicações autorizadas pedem um token válido sempre que acedem ao serviço em nome da pessoa, sem guardarem os tokens.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Uma função de administração e suporte é atribuída à sua equipa, como suporte ou operações, em todo o ambiente. Aplica-se a todas as organizações, e os administradores de nenhuma organização a podem ver, atribuir ou remover. Uma função própria de uma aplicação atribuída desta forma aplica-se apenas a essa aplicação.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Um ambiente é um serviço de identidade completamente isolado, com os seus próprios utilizadores, chaves, início de sessão e emissor. Todos os ambientes desta instalação aparecem aqui com a organização proprietário. Crie um, selecione-o na consola e adicione a primeira organização e o primeiro administrador.',
