    'the_identifier_the_application_calls_itself_in_its_auth_afe05ddf' => 'O identificador com que a aplicação se identifica nos seus AuthnRequests.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Um telemóvel com a aplicação autenticadora instalada permite responder a pedidos de aprovação e receber avisos quando alguém inicia sessão na sua conta. Registe-o uma vez lendo o código. Se perder o telemóvel, remova-o aqui de imediato para impedir novas aprovações.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Uma organização é a área de uma empresa registada nesta instalação, com os seus projetos, ambientes e equipa. Abra-o para consultar os produtos e ambientes ou suspenda-o: isso termina as sessões dos membros e impede novos inícios de sessão em todos os ambientes que lhe pertencem.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Quando uma aplicação ou um agente de IA precisa da sua autorização para agir em seu nome, nem sempre pode pedi-la no ecrã à sua frente; por isso, pede-a aqui. Aprove apenas pedidos que iniciou e confirme que o código apresentado corresponde ao código no dispositivo que fez o pedido.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Um projeto representa um dos seus produtos, com plano, início de sessão e ambientes próprios, como produção e pré-produção. Abra um ambiente a partir daqui para o administrar. Crie um novo projeto ao lançar um produto que deva ter faturação e funcionamento independentes.',
