    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'O bucket fica no caminho em vez de no nome do host. Um endpoint personalizado já utiliza este formato.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Cada aplicação que autentica pessoas através do Cbox ID ou chama a sua API é registada aqui e recebe credenciais próprias. Faça um registo por aplicação e por ambiente. Nunca partilhe credenciais entre eles, para poder revogar um registo sem interromper os restantes.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Procura uma organização pelo nome ou identificador, ou um utilizador pelo nome ou email, em todos os ambientes desta instalação, e não apenas no selecionado na consola. Use esta pesquisa quando alguém pedir ajuda e não souber em que ambiente está.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Veja uma aplicação exatamente como um dos seus utilizadores: inicie sessão em nome dessa pessoa, indicando o motivo, durante no máximo uma hora. A aplicação é informada de quem está realmente a aceder e não recebe meios para manter a sessão. O registo de auditoria da organização guarda quem o fez e porquê.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Um projeto representa um produto IdP desta organização e é ao projeto que os ambientes pertencem. Até que a organização crie um projeto na sua própria consola, não há aqui nenhum ambiente para selecionar ou abrir. Este ecrã não permite criar um projeto em nome da organização.',
