    'the_hosted_sign_in_s_look_logo_and_favicon_and_the_name_39304e21' => 'O aspeto, o logótipo e o favicon do início de sessão alojado, bem como o nome e o remetente apresentados aos utilizadores.',
    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Enviado quando é criada uma conta. Deixe em branco para usar a predefinição.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Apenas para fornecedores que não publicam as chaves de assinatura (jwks_uri) no documento de descoberta. Caso contrário, as chaves são lidas daí, incluindo as rotações. Introduza uma chave pública PEM. É guardada encriptada e nunca volta a ser apresentada; deixe vazio para manter a atual.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Alguns pares de funções nunca devem ser atribuídos à mesma pessoa: quem inicia um pagamento não deve também aprová-lo. Declare esses pares aqui. O Cbox ID bloqueia novas atribuições que violem a regra e mostra quem já tem um par de funções incompatíveis.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Chaves de API e tokens de que as aplicações e os agentes precisam para outros serviços, guardados aqui encriptados em vez de na configuração de cada aplicação. Introduza o segredo uma vez e autorize aplicações específicas a usá-lo. Não volta a ser apresentado; se o perder, substitua-o.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Disponibiliza os endpoints de identidade de um ambiente num domínio seu, como login.example.com, em vez de num domínio nosso. Comprove que o domínio lhe pertence através de um registo DNS TXT. Configure-o para que as pessoas vejam apenas o seu endereço ao iniciar sessão.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'O nome da organização que reúne os projetos, ambientes e equipa e que aparece em toda a consola. Eliminar uma organização desativa todos os ambientes usados para iniciar sessão. Por isso, a eliminação é pedida ao suporte, em vez de feita por um botão.',
    'the_claim_is_dropped_if_capture_was_on_people_on_this_d_17d5c40e' => 'A reivindicação do domínio é removida. Se o SSO obrigatório estava ativado, as pessoas deste domínio voltam ao início de sessão normal.',
    'this_domain_will_no_longer_route_its_users_through_this_281a9227' => 'Este domínio deixa de encaminhar os utilizadores para o SSO desta organização. Esta ação é irreversível.',
    'this_client_can_no_longer_lease_the_secret_any_lease_it_c5728383' => 'Este cliente deixa de poder obter acesso temporário ao segredo. As concessões de acesso já existentes mantêm-se válidas até expirarem.',
    'this_endpoint_stops_receiving_events_and_its_delivery_h_b6a65cf3' => 'Este endpoint deixa de receber eventos e o histórico de entregas é eliminado. Esta ação é irreversível.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_789a1199' => 'Tudo o que o titular tenha configurado para usar esta chave deixa de funcionar imediatamente. Esta ação é irreversível.',
    'the_name_of_the_organization_these_identity_providers_a_72767cbb' => 'O nome da organização ao qual pertencem a faturação e a administração destes fornecedores de identidade.',
    'the_plan_allowance_on_their_first_product_billing_hangs_f5035935' => 'Os limites do plano do primeiro produto. A faturação está associada ao produto, não à organização.',
    'this_project_has_no_environments_yet_nothing_under_it_s_a2247eb5' => 'Este projeto ainda não tem ambientes. Não há nenhum serviço de autenticação a funcionar neste projeto.',
    'this_project_has_used_every_environment_its_plan_allows_b891ec0b' => 'Este projeto atingiu o número de ambientes permitido pelo plano. Mude para um plano superior para adicionar mais.',
