    'local_or_reserved_address_1bfdaa4f' => 'Endereço local ou reservado',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Cada organização representa uma empresa ou equipa que usa o seu produto, com membros, funções, domínios e início de sessão único próprios. Crie uma por empresa registada. Abra-a para gerir membros, convites e domínios verificados ou para a suspender.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'O Cbox ID envia uma mensagem assinada para o seu endpoint depois de um acontecimento, como a entrada de um membro ou a alteração de uma função, para os seus sistemas reagirem sem consultas periódicas. As entregas são repetidas em caso de falha. O acontecimento já ocorreu: o endpoint é informado, não decide o resultado.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Um esquema define a estrutura dos eventos de uma ação: os tipos de destino que identificam e o conteúdo dos metadados. Os eventos de uma ação com esquema são validados à chegada. Sem esquema, são aceites tal como enviados, exceto se o modo estrito estiver ativo.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Todas as pessoas que administram esta organização, a função integrada de cada uma — Proprietário, Administrador, Programador, Membro ou Leitor — e os ambientes a que podem aceder. Convide pessoas por email e conceda a cada uma acesso apenas aos ambientes necessários ao seu trabalho.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Permita que os utilizadores das suas aplicações liguem as próprias contas GitHub, Google, Slack ou Salesforce, para as aplicações chamarem essas APIs em seu nome. Os tokens são guardados encriptados e atualizados aqui, sendo disponibilizados temporariamente apenas às aplicações autorizadas.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'A pessoa convidada aceita por email. Ninguém é adicionado a uma organização sem dar o seu consentimento.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Este utilizador não tem sessões iniciadas neste momento. As sessões aparecem aqui quando iniciar sessão.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Este utilizador tem de alterar a palavra-passe. Não pode aceder a nada até substituir a que lhe forneceu.',
    'user_created_they_have_no_way_to_sign_in_until_you_send_a612f0b1' => 'Utilizador criado. Só poderá iniciar sessão depois de lhe enviar uma ligação.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Dados do utilizador apagados. A conta foi pseudonimizada e a eliminação foi registada como user.erased no registo de auditoria.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Os operadores da plataforma administram todas as organizações e ambientes desta instalação, acima do âmbito de qualquer um deles. Adicione um operador apenas se for responsável pela própria instalação e suspenda-o assim que deixar de desempenhar essa função.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Todas as organizações do ambiente selecionado na consola, numa árvore de revendedores, organizações geridas por eles e respetivas subunidades. Aqui pode criar ou suspender uma organização, ou movê-la para outra organização superior.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Inícios de sessão, tokens emitidos, novos utilizadores e registos de autenticação de dois fatores, por dia, nos últimos 30 dias, salvo se a instalação definir outro período. A página fica vazia até o responsável pela instalação configurar o armazenamento das análises.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Defina esta política de confiança para a função (IAM › Roles › Trust relationships). A plataforma só pode assumir a função quando apresenta o ID externo deste fluxo, impedindo que outros utilizadores da plataforma direcionem um fluxo para a sua função.',
    'their_it_contact_left_blank_you_copy_the_lin_2fe54822' => 'O contacto de TI. Se ficar em branco, terá de copiar a ligação.',
    'presets_colours_corners_type_edited_with_a_live_preview_ff61e898' => 'Predefinições, cores, cantos e tipografia, com pré-visualização em tempo real.',
    'where_a_copy_of_every_audit_entry_is_delivered_as_it_is_c6b9e401' => 'Onde é entregue uma cópia de cada registo de auditoria assim que é criado.',
    'where_sign_ins_go_for_people_who_have_not_moved_to_cbox_be5f68b3' => 'Para onde são encaminhados os inícios de sessão das pessoas que ainda não migraram para o Cbox ID.',
    'where_the_provider_posts_its_assertion_give_this_to_who_5b098f34' => 'Onde o fornecedor envia a asserção. Entregue este endereço a quem configura o IdP.',
    'where_the_signed_assertion_is_posted_back_must_be_https_2dc6e396' => 'Onde é devolvida a asserção assinada. Tem de usar https.',
    'where_we_exchange_the_client_credentials_for_a_short_li_2afa7c75' => 'Onde trocamos as credenciais do cliente por um token de curta duração antes de cada lote.',
    'who_connected_an_account_through_this_pipe_tokens_are_n_ea456475' => 'Quem ligou uma conta através desta ligação. Os tokens nunca são apresentados.',
    'this_connection_belongs_to_the_environment_itself_it_si_543963d3' => 'Esta ligação pertence ao próprio ambiente. Autentica as pessoas sem as adicionar a nenhuma organização.',
    'this_organization_s_entries_and_nothing_from_any_other_1ab06e62' => 'Os registos desta organização, sem registos de qualquer outra.',
    'what_you_create_here_belongs_to_this_organization_and_t_fc8e15c4' => 'O que criar aqui pertence apenas a esta organização.',
    'whose_people_are_pushed_or_tick_the_box_above_to_send_e_bb15010f' => 'De que organização são as pessoas a sincronizar. Também pode selecionar a opção acima para enviar todas as organizações.',
    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'De que organização são as pessoas que iniciam sessão através desta ligação. Os domínios e a ligação para o Portal de administração estão na página dessa organização.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Todos os navegadores e dispositivos com sessão iniciada na sua conta, as aplicações autorizadas a agir em seu nome e os inícios de sessão e alterações de segurança recentes. Se não reconhecer uma atividade, termine a sessão ou revogue a aplicação e depois altere a palavra-passe.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Todas as alterações feitas nesta organização: quem fez o quê, sobre que elemento e quando. As entradas estão ligadas por hashes, por isso remover ou alterar uma quebra a cadeia e torna a intervenção detetável. Só permite leitura, intencionalmente: é o registo que entrega a um auditor.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Deixe vazio para quase todos os fornecedores: os tokens de identidade são verificados com as chaves de assinatura publicadas no documento de descoberta (jwks_uri), incluindo as rotações. Cole a chave pública PEM do fornecedor apenas se não publicar nenhuma.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Inícios de sessão e pedidos que o Cbox ID classificou como suficientemente arriscados para sinalizar, dos mais recentes para os mais antigos, com a pontuação e os motivos. Consulte após um aumento de falhas de início de sessão ou quando alguém comunicar um acesso que não fez.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Este ambiente disponibiliza um servidor MCP além da API REST. Ligue um agente com uma chave de gestão e ele poderá fazer exatamente o que os âmbitos da chave permitem, com as mesmas verificações, aprovações e registo de auditoria da consola.',
    'nothing_recorded_matches_these_filters_widen_the_range_804705cd' => 'Nenhum registo corresponde a estes filtros. Alargue o intervalo ou remova um filtro.',
    'searches_organizations_and_users_across_every_environme_031a8626' => 'Pesquisa organizações e utilizadores em todos os ambientes desta instalação.',
    'the_ten_organizations_with_the_most_members_and_the_env_1c7ea5a5' => 'As dez organizações com mais membros e o ambiente a que cada uma pertence',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Quem tem uma sessão iniciada como esta pessoa neste momento. O Radar mostra por que motivo um início de sessão foi permitido, sujeito a verificação adicional ou bloqueado.',
    'what_this_organization_s_sign_in_is_wired_to_read_from_cde71601' => 'A que está ligado o início de sessão desta organização, com base na configuração real.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'O fornecedor próprio de uma organização substitui o do ambiente na página de início de sessão dessa organização. Também são listadas as organizações que desativaram o fornecedor do ambiente. Isso apenas remove o botão da página; para impedir o acesso por esse método, é preciso exigir SSO.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'As aplicações com uma lista própria de utilizadores ficam desatualizadas assim que alguém entra ou sai. Uma ligação SCIM envia-lhes cada alteração no momento em que ocorre, incluindo as saídas, que são as mais fáceis de esquecer.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Configure um fornecedor de identidade para usar o nosso endpoint SCIM, ligue o Google Workspace ou Microsoft Entra, ou ligue o seu sistema de recursos humanos — Workday, BambooHR, Rippling, HiBob ou Personio. Iremos importar os dados das pessoas periodicamente.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'O registo de auditoria está aqui, mas as ferramentas da equipa de segurança estão noutro sítio. Um fluxo envia-lhes uma cópia de cada entrada assim que é escrita, para uma investigação não começar com um pedido de exportação CSV.',
