    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Escolha SCIM se o fornecedor nos enviar os dados, Google Workspace ou Entra se os formos obter, ou o seu sistema de recursos humanos — Workday, BambooHR, Rippling, HiBob ou Personio — para que as pessoas sejam criadas na data de entrada.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Inclui as chaves das funcionalidades ativas para a pessoa, na organização em que iniciou sessão, no token de acesso, no token de ID e no UserInfo, na declaração `feature_flags`.',
    'puts_everything_userinfo_answers_for_the_app_s_scopes_e_db47369d' => 'Inclui no token de ID tudo o que o UserInfo devolve para os âmbitos da aplicação (email, nome, funções, permissões, organizações), para que a aplicação possa dispensar a chamada ao UserInfo no início de sessão. Apenas para uma aplicação que envia `id_token_hint` por POST ao terminar sessão, ou que não o envia: um token num URL fica escrito nos registos de acesso.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'O botão desaparece da página de início de sessão desta organização — o do ambiente não o substitui. As credenciais são mantidas, para poder voltar a ativá-lo.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Esta credencial exige a aprovação de uma pessoa para esta ação, mas não há nenhuma pessoa registada que a possa dar. Execute a ação na consola ou crie uma chave na consola cujo proprietário possa aprová-la.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Este endpoint pertence ao ambiente e é acionado para todas as organizações nele contidas. Aparece aqui porque intervém nos seus inícios de sessão; é gerido pelo operador.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Não foi possível enviar o e-mail agora — esta instalação não consegue contactar o servidor de correio. Tente mais tarde; um administrador também pode confirmar o seu endereço com `php artisan cbox-id:users:confirm-email`.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Quando uma aplicação ou um agente precisa da sua autorização para agir em seu nome, pede-a aqui. Aprove apenas pedidos que iniciou.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Veja se o trabalho em segundo plano desta instalação — webhooks, avisos de fim de sessão para aplicações ligadas e emails em fila — está efetivamente a ser enviado.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Precisa de credenciais da sua própria conta no fornecedor, normalmente um ID e um segredo de cliente. A Apple emite uma chave de assinatura em vez do segredo.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'O seu endpoint é chamado durante uma operação e a resposta altera o resultado: pode acrescentar dados a um token ou recusar o início de sessão.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Os seus endpoints recebem uma mensagem assinada após um acontecimento, para os seus sistemas reagirem sem consultas constantes.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'O nome, os domínios e as predefinições da organização. As alterações aplicam-se a todas as pessoas que iniciam sessão através desta organização.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'As suas credenciais em cada fornecedor, disponibilizadas em todas as páginas de início de sessão deste ambiente. Todas as organizações do ambiente as herdam.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'As suas credenciais em cada fornecedor, disponibilizadas a todas as pessoas deste ambiente. Todas as organizações as herdam.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'O recetor guarda o mesmo segredo, usado exatamente como apresentado, incluindo o prefixo whsec_, como chave HMAC para X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'A sua página de início de sessão apresenta o seu logótipo e as suas cores. As pessoas introduzem lá uma palavra-passe — deve reconhecer-se a sua marca, não a nossa.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'O sua organização: projetos, equipa, chaves e faturação. O início de sessão das suas aplicações é configurado na consola de cada ambiente.',
    'a_management_key_reads_and_writes_this_envir_aba5f345' => 'Uma chave de gestão lê e altera as organizações e os utilizadores deste ambiente através da API, e o seu valor é mostrado uma única vez.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Não tem permissões em :part1, pelo que uma chave apenas o identificaria nessa aplicação, sem permitir mais nada.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Só são disponibilizadas as ações que pode realizar em :part1. Se mais tarde perder uma permissão, a chave também a perde.',
